:linear-gradient(145deg,#171d37,#101429)}.duel-phase{display:flex;align-items:center;gap:8px;color:var(--dr-green);font-size:11px;font-weight:750;text-transform:uppercase;letter-spacing:.06em}.duel-live-dot{width:7px;height:7px;border-radius:50%;background:var(--dr-green);box-shadow:0 0 12px var(--dr-green)}.duel-phase b{margin-inline-start:auto;color:var(--dr-text);font-variant-numeric:tabular-nums}.duel-view{display:grid;gap:10px;margin-top:13px}.duel-match{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:10px;padding:14px;border:1px solid var(--dr-line);border-radius:14px;background:#0c1124;text-align:center}.duel-match strong{font-size:12px;font-weight:650}.duel-match b{font-size:18px;font-variant-numeric:tabular-nums}.duel-match small{color:var(--dr-muted);font-size:9px}.duel-event-list{display:grid;gap:6px;margin-top:9px}.duel-event{display:flex;align-items:center;gap:8px;color:var(--dr-muted);font-size:11px;padding:8px 10px;border-radius:10px;background:rgba(255,255,255,.025)}.duel-event b{color:var(--dr-green);font-variant-numeric:tabular-nums}.duel-builder{margin-top:17px;padding-top:16px;border-top:1px solid var(--dr-line)}.duel-builder>header{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.duel-builder h2{font-size:18px;font-weight:700;margin:4px 0}.duel-builder p{font-size:11px;color:var(--dr-muted);margin:0}.duel-budget{padding:8px 10px;border-radius:10px;background:rgba(0,233,138,.1);color:var(--dr-green);font-size:11px;font-weight:800;white-space:nowrap}.duel-builder__tools{display:grid;grid-template-columns:140px minmax(100px,1fr) auto;gap:8px;margin:13px 0}.duel-builder__tools select,.duel-builder__tools input[type=search],#duel-invite input,#duel-chat-form input{width:100%;min-width:0;height:40px;padding:0 11px;border:1px solid var(--dr-line);border-radius:10px;background:#0c1124;color:var(--dr-text);font:inherit;font-size:11px}.duel-builder__tools label{display:flex;align-items:center;gap:6px;color:var(--dr-muted);font-size:10px;white-space:nowrap}.duel-slot-summary{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:9px}.duel-slot{padding:5px 8px;border:1px solid var(--dr-line);border-radius:999px;color:var(--dr-muted);font-size:9px}.duel-slot b{color:var(--dr-text)}.duel-player-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;max-height:400px;overflow:auto;overscroll-behavior:contain}.duel-player{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:6px;padding:8px;border:1px solid var(--dr-line);border-radius:11px;background:#0c1124;cursor:pointer}.duel-player:hover,.duel-player.is-selected{border-color:rgba(0,233,138,.45);background:rgba(0,233,138,.07)}.duel-player.is-disabled{opacity:.45;cursor:not-allowed}.duel-player strong{overflow:hidden;display:block;font-size:10px;text-overflow:ellipsis;white-space:nowrap}.duel-player small{display:block;color:var(--dr-muted);font-size:9px;margin-top:2px}.duel-player b{color:var(--dr-green);font-size:10px;white-space:nowrap}.duel-player button{padding:4px;border:0;background:transparent;color:var(--dr-green);font-size:9px}.duel-action{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:43px;padding:0 14px;border:0;border-radius:11px;background:var(--dr-green);color:#06271b!important;font:inherit;font-size:11px;font-weight:800;cursor:pointer}.duel-action--soft{border:1px solid var(--dr-line);background:#212845;color:var(--dr-text)!important}.duel-room__error{min-height:15px;color:#ff879d;font-size:11px}.duel-verify{margin-top:15px}.duel-side{display:grid;align-content:start;gap:17px}.duel-side section+section{padding-top:14px;border-top:1px solid var(--dr-line)}.duel-side h2{font-size:13px;font-weight:700;margin:0 0 10px}.duel-side h2 i{color:var(--dr-green);margin-inline-end:5px}.duel-players,.duel-standings{display:grid;gap:6px}.duel-person,.duel-standing{display:flex;justify-content:space-between;gap:8px;align-items:center;padding:8px 9px;border-radius:10px;background:#0c1124;color:var(--dr-muted);font-size:10px}.duel-person strong,.duel-standing strong{color:var(--dr-text);font-weight:650}.duel-standing b{color:var(--dr-green);white-space:nowrap}.duel-person .ready-mark{color:var(--dr-green)}#duel-ready{width:100%;margin-top:9px}#duel-invite{display:grid;gap:7px;margin-top:9px}#duel-invite .duel-action{width:100%;min-height:38px}#duel-invite input{height:38px}.duel-chat{display:grid;align-content:start;gap:6px;max-height:210px;overflow:auto}.duel-chat p{margin:0;padding:7px 8px;background:#0c1124;border-radius:9px;color:var(--dr-muted);font-size:10px;line-height:1.45;overflow-wrap:anywhere}.duel-chat p b{color:var(--dr-text)}#duel-chat-form{display:flex;gap:6px;margin-top:7px}#duel-chat-form button{flex:0 0 40px;border:0;border-radius:10px;background:var(--dr-green);color:#06271b}#duel-chat-form input{height:40px}.duel-verify p{font-size:11px;color:var(--dr-muted);overflow-wrap:anywhere}@media(max-width:760px){.duel-room__hero{align-items:flex-start;flex-direction:column}.duel-room__meta{width:100%}.duel-room__meta span{flex:1;min-width:0}.duel-room__grid{grid-template-columns:minmax(0,1fr)}.duel-side{grid-row:2}.duel-player-grid{max-height:340px}}@media(max-width:450px){.duel-room{padding:9px}.duel-room__commit{align-items:flex-start;flex-direction:column}.duel-room__commit code{width:100%}.duel-builder__tools{grid-template-columns:1fr 1fr}.duel-builder__tools input[type=search]{grid-column:1/-1;grid-row:1}.duel-builder__tools label{justify-content:flex-end}.duel-player-grid{grid-template-columns:1fr}.duel-match{padding:11px 8px;gap:5px}.duel-match strong{font-size:10px}.duel-match b{font-size:16px}}
</style>
