@push('script')
<script>
(()=>{
const root=document.querySelector('#duel-room');if(!root)return;const csrf=root.dataset.csrf;let state=@json($snapshot);let cursor=state.event_cursor||0;let catalog=state.player_catalog||[];let picked=new Set(state.my_squad?.player_ids||[]);let captain=state.my_squad?.captain_id||null;let chatIds=new Set();const $=s=>document.querySelector(s),headers={'Accept':'application/json','X-CSRF-TOKEN':csrf,'Content-Type':'application/json'};
function esc(s){const e=document.createElement('span');e.textContent=s??'';return e.innerHTML}function slots(){return picked.size;}function renderPlayers(){const q=$('#duel-search').value.trim().toLowerCase(),pos=$('#duel-position').value,aff=$('#duel-affordable').checked;const selected=catalog.filter(p=>picked.has(p.id));const spend=selected.reduce((a,p)=>a+p.price,0),balance=Number(state.tier)-spend;$('#duel-budget').textContent=`${spend.toFixed(1)} / ${Number(state.tier).toFixed(1)} credits · ${(balance).toFixed(1)} left`;const counts={GK:0,DEF:0,MID:0,FWD:0};selected.forEach(p=>counts[p.position]=(counts[p.position]||0)+1);$('#duel-slots').innerHTML=['GK','DEF','MID','FWD'].map(p=>`<span class="duel-slot">${p} <b>${counts[p]||0}</b></span>`).join('')+`<span class="duel-slot"><b>${11-picked.size}</b> slots left</span>`;const minCost={GK:Math.min(...catalog.filter(p=>p.position==='GK').map(p=>p.price)),DEF:Math.min(...catalog.filter(p=>p.position==='DEF').map(p=>p.price)),MID:Math.min(...catalog.filter(p=>p.position==='MID').map(p=>p.price)),FWD:Math.min(...catalog.filter(p=>p.position==='FWD').map(p=>p.price))};let html='';catalog.filter(p=>{if(pos&&p.position!==pos)return false;if(q&&!`${p.name} ${p.club}`.toLowerCase().includes(q))return false;if(picked.has(p.id))return true;const same=selected.filter(x=>x.position===p.position).length;const maxPer=p.position==='GK'?1:p.position==='DEF'?5:p.position==='MID'?5:3;if(same>=maxPer||selected.filter(x=>x.club_id===p.club_id).length>=3)return false;const minimumNeed={GK:Math.max(0,1-counts.GK),DEF:Math.max(0,3-counts.DEF),MID:Math.max(0,2-counts.MID),FWD:Math.max(0,1-counts.FWD)};let reserve=0;for(const [k,n] of Object.entries(minimumNeed)){let available=n-(k===p.position?1:0);reserve+=Math.max(0,available)*minCost[k];}const maxPrice=balance-reserve;return !aff||p.price<=maxPrice+0.001;}).slice(0,180).forEach(p=>{let chosen=picked.has(p.id);html+=`<button type="button" class="duel-player ${chosen?'is-selected':''}" data-player="${p.id}"><span><strong>${esc(p.name)}</strong><small>${esc(p.position)} · ${esc(p.club)}</small></span><b>${p.price.toFixed(1)}</b></button>`});$('#duel-player-grid').innerHTML=html||'<p class="duel-room__error">No players match these filters.</p>';$('#duel-player-grid').querySelectorAll('[data-player]').forEach(btn=>btn.onclick=()=>{const id=Number(btn.dataset.player),p=catalog.find(x=>x.id===id);if(picked.has(id)){picked.delete(id);if(captain===id)captain=null;}else if(picked.size<11){picked.add(id);if(!captain)captain=id;}renderPlayers();});$('#duel-submit-squad').disabled=picked.size!==11||!captain;}
function render(s){state=s;catalog=s.player_catalog||catalog;$('#duel-phase-label').textContent=s.phase.replaceAll('_',' ');$('#duel-clock').textContent=s.deadline?new Date(s.deadline).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}):'';$('#duel-players').innerHTML=(s.players||[]).map(p=>`<div class="duel-person"><strong>${esc(p.username)} ${p.is_you?'· you':''}</strong><span>${p.ready?'<i class="las la-check ready-mark"></i> Ready':'Waiting'}</span></div>`).join('')||'<small>Waiting for players…</small>';$('#duel-ready').hidden=!s.ready;$('#duel-ready').disabled=!!s.players?.find(p=>p.is_you&&p.ready);$('#duel-ready').textContent=$('#duel-ready').disabled?'Ready ✓':"I'm ready";$('#duel-invite').hidden=!(s.phase==='lobby'&&s.players?.some(p=>p.is_you));$('#duel-builder').hidden=!s.can_build;$('#duel-verify').hidden=s.phase!=='finished';$('#duel-view').innerHTML=(s.matches||[]).map((m,i)=>`<div class="duel-match"><div><strong>${esc(m.home)}</strong><br><small>HOME · ${i+1}</small></div><b>${m.home_score} : ${m.away_score}</b><div><strong>${esc(m.away)}</strong><br><small>AWAY</small></div></div>`).join('');$('#duel-standings').innerHTML=(s.standings||[]).map((p,i)=>`<div class="duel-standing"><strong>${i+1}. ${esc(p.username)}${p.is_you?' · you':''}${p.auto?' · auto XI':''}</strong><b>${p.points} pts</b></div>`).join('')||'<small>Scores appear when the matches go live.</small>';const list=$('#duel-view');let events=document.querySelector('#duel-events');if(!events){events=document.createElement('div');events.id='duel-events';events.className='duel-event-list';list.append(events);}if(s.events?.length){for(const e of s.events){const key=`${e.match}-${e.minute}-${e.type}-${e.player}`;if(chatIds.has(key))continue;chatIds.add(key);const row=document.createElement('div');row.className='duel-event';row.innerHTML=`<b>${e.minute}'</b><span>Match ${e.match} · ${esc(e.player)} · ${esc(e.type.replaceAll('_',' '))}</span>`;events.append(row)}}if(s.can_build)renderPlayers();}
let duelTimeline=[];const baseRender=render;render=function(s){if(s.events?.length)duelTimeline.push(...s.events);baseRender(s);$('#duel-join').hidden=s.is_seated||s.status!=='waiting';const timeline=$('#duel-events');if(timeline)timeline.innerHTML=duelTimeline.map(e=>`<div class="duel-event"><b>${e.minute}'</b><span>Match ${e.match} · ${esc(e.player)} · ${esc(e.type.replaceAll('_',' '))}</span></div>`).join('');};
const baseRenderPlayers=renderPlayers;renderPlayers=function(){baseRenderPlayers();const select=$('#duel-captain'),options=catalog.filter(p=>picked.has(p.id));select.innerHTML='<option value="">Choose from your XI</option>'+options.map(p=>`<option value="${p.id}">${esc(p.name)} · ${p.position}</option>`).join('');select.value=captain||'';$('#duel-submit-squad').disabled=picked.size!==11||!captain;};
$('#duel-captain').addEventListener('change',e=>{captain=Number(e.target.value)||null;});
async function getSnapshot(){try{const r=await fetch(root.dataset.snapshot+'?event_cursor='+cursor,{headers:{'Accept':'application/json'}});if(!r.ok)return;const s=await r.json();cursor=s.event_cursor||cursor;render(s);}catch(e){}}
async function post(url,data={}){const r=await fetch(url,{method:'POST',headers,body:JSON.stringify(data)});const d=await r.json();if(!r.ok)throw Error(d.message||'The request could not be completed.');return d;}
$('#duel-ready').onclick=async()=>{try{render(await post(root.dataset.ready));}catch(e){alert(e.message)}};
$('#duel-join').onclick=async()=>{try{await post(root.dataset.join);location.reload();}catch(e){alert(e.message)}};
$('#duel-position').onchange=renderPlayers;$('#duel-search').oninput=renderPlayers;$('#duel-affordable').onchange=renderPlayers;
$('#duel-submit-squad').onclick=async()=>{const error=$('#duel-builder-error');error.textContent='';try{const d=await post(root.dataset.squad,{player_ids:[...picked],captain_id:captain});render(d);}catch(e){error.textContent=e.message}};
$('#duel-player-grid').addEventListener('contextmenu',e=>{const btn=e.target.closest('[data-player]');if(!btn)return;e.preventDefault();const id=Number(btn.dataset.player);if(picked.has(id)){captain=id;renderPlayers();}});
$('#duel-verify-button').onclick=async()=>{const out=$('#duel-verify-result');out.textContent='Checking the commitment and replaying each virtual match…';try{const r=await fetch(root.dataset.verify,{headers:{'Accept':'application/json'}}),d=await r.json();if(!r.ok)throw Error(d.message||'Could not verify this slate.');out.textContent=d.valid?'Verified: seed commitment and every match simulation match.':'Verification failed. Save this table ID and contact support.';}catch(e){out.textContent=e.message}};
$('#duel-invite').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;try{const r=await fetch(form.action,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json','Content-Type':'application/json'},body:JSON.stringify({username:form.username.value})}),d=await r.json();if(!r.ok)throw Error(d.message||'Invite could not be sent.');form.username.value='';}catch(err){alert(err.message)}};
async function getChat(){try{const r=await fetch(root.dataset.chat,{headers:{'Accept':'application/json'}});if(!r.ok)return;const d=await r.json();for(const m of d.messages||[]){if(chatIds.has(`chat-${m.id}`))continue;chatIds.add(`chat-${m.id}`);const p=document.createElement('p');p.innerHTML=`<b>${esc(m.name)}:</b> ${esc(m.body||m.attachment_name||'Attachment')}`;$('#duel-chat').append(p)}$('#duel-chat').scrollTop=$('#duel-chat').scrollHeight;}catch(e){}}
$('#duel-chat-form').onsubmit=async e=>{e.preventDefault();const input=e.currentTarget.body;if(!input.value.trim())return;try{const form=new FormData();form.append('body',input.value.trim());form.append('kind','text');const r=await fetch(root.dataset.chatSend,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:form});const d=await r.json();if(!r.ok)throw Error(d.message||'Message could not be sent.');input.value='';getChat();}catch(err){alert(err.message)}};
render(state);getChat();setInterval(()=>{if(!document.hidden)getSnapshot()},3500);setInterval(()=>{if(!document.hidden)getChat()},4500);
})();
</script>
@endpush
